"""A "PNG" button that downloads an image of a styled table.

Everything happens in the browser when the button is clicked, so nothing is rendered on the
server and Streamlit Cloud's fragile kaleido isn't involved: the pandas Styler HTML (the same
colours and number formats as the on-screen table) is laid out off-screen with a title above and
a note below, then captured with html2canvas. html2canvas is loaded from jsDelivr on the first
click only. Same approach as cost-of-carry-calculator's snapshot Copy button.
"""
from __future__ import annotations

import streamlit as st

HTML2CANVAS_ESM = "https://cdn.jsdelivr.net/npm/html2canvas@1.4.1/+esm"

_HTML = """
<button type="button" class="jsa-png-btn" title="Download this table as a PNG image">PNG</button>
"""

_CSS = """
/* Dressed like Streamlit's own buttons beside it (Copy, CSV). */
.jsa-png-btn {
  width: 90px; height: 2.5rem; padding: 0 0.75rem; cursor: pointer;
  font: inherit; font-size: 1rem; color: inherit;
  background: var(--st-background-color, #ffffff);
  border: 1px solid color-mix(in srgb, currentColor 20%, transparent); border-radius: 0.5rem;
  white-space: nowrap;
}
.jsa-png-btn:hover { border-color: var(--st-primary-color, #ff4b4b); color: var(--st-primary-color, #ff4b4b); }
.jsa-png-btn:disabled { opacity: 0.6; cursor: progress; }
"""

_JS = f"""
const HTML2CANVAS_ESM = "{HTML2CANVAS_ESM}";

async function tableBlob(data) {{
  const mod = await import(HTML2CANVAS_ESM);
  const html2canvas = mod.default || mod;
  const host = document.createElement("div");
  host.style.cssText = "position:fixed;left:-100000px;top:0;background:#fff;padding:14px;" +
    "display:inline-block;font-family:'Source Sans Pro',Arial,sans-serif;font-size:13px;color:#31333f;";
  const style = document.createElement("style");
  style.textContent =
    ".jsa-png-table table{{border-collapse:collapse;}}" +
    ".jsa-png-table th,.jsa-png-table td{{padding:5px 10px;border-bottom:1px solid #e6e9ef;" +
    "white-space:nowrap;text-align:right;}}" +
    ".jsa-png-table th{{font-weight:600;color:#555;background:#f7f8fa;}}" +
    ".jsa-png-table td:first-child,.jsa-png-table th:first-child{{text-align:left;}}" +
    ".jsa-png-title{{font-size:16px;font-weight:600;color:#1f2933;margin:0 0 8px;}}" +
    ".jsa-png-note{{font-size:11px;line-height:1.4;color:#6b7280;margin-top:8px;}}";
  const wrap = document.createElement("div");
  wrap.className = "jsa-png-table";
  wrap.style.position = "relative";
  if (data.title) {{
    const head = document.createElement("div");
    head.className = "jsa-png-title";
    head.textContent = data.title;
    wrap.appendChild(head);
  }}
  const body = document.createElement("div");
  body.innerHTML = data.html;
  wrap.appendChild(body);
  host.appendChild(style);
  host.appendChild(wrap);
  document.body.appendChild(host);
  try {{
    if (data.note) {{
      const note = document.createElement("div");
      note.className = "jsa-png-note";
      note.textContent = data.note;
      // Wrap the note at the table's width rather than letting it stretch the image.
      const table = body.querySelector("table");
      if (table) note.style.maxWidth = table.offsetWidth + "px";
      wrap.appendChild(note);
    }}
    if (data.watermark) {{
      const mark = document.createElement("img");
      mark.src = data.watermark;
      mark.style.cssText = "position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);" +
        "max-width:34%;max-height:80%;opacity:0.10;pointer-events:none;";
      wrap.appendChild(mark);
      if (!mark.complete) await new Promise((ok) => {{ mark.onload = ok; mark.onerror = ok; }});
    }}
    const canvas = await html2canvas(host, {{ scale: 2, backgroundColor: "#ffffff", logging: false }});
    return await new Promise((ok) => canvas.toBlob(ok, "image/png"));
  }} finally {{
    host.remove();
  }}
}}

function download(blob, filename) {{
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob);
  a.download = filename + ".png";
  a.click();
  setTimeout(() => URL.revokeObjectURL(a.href), 5000);
}}

export default function (component) {{
  const {{ data, parentElement }} = component;
  const btn = parentElement.querySelector(".jsa-png-btn");
  if (!btn || !data) return;

  const flash = (text) => {{
    btn.textContent = text;
    setTimeout(() => {{ btn.textContent = "PNG"; btn.disabled = false; }}, 1800);
  }};

  btn.onclick = async () => {{
    btn.disabled = true;
    btn.textContent = "Saving…";
    try {{
      download(await tableBlob(data), data.filename);
      flash("Saved ✓");
    }} catch (e) {{
      flash("Failed");
    }}
  }};
}}
"""

def _component():
    """The button, registered on every call rather than once at import: re-registering the same
    definition is a no-op, while a module that outlives the runtime's component registry (a
    test harness, an app host that swaps pages) would otherwise keep a component it forgot."""
    return st.components.v2.component(
        "jsa_table_png", html=_HTML, css=_CSS, js=_JS, isolate_styles=False,
    )


def table_png_button(styler, filename: str, key: str, title: str = "", note: str = "",
                     watermark_uri: str | None = None) -> None:
    """PNG download for a table, snapshotting the Styler's HTML (colours and formats)."""
    html = styler.hide(axis="index").to_html()
    _component()(key=f"tablepng_{key}", width=90,
                 data={"html": html, "title": title, "note": note, "watermark": watermark_uri,
                       "filename": filename})
